document.addEventListener('DOMContentLoaded', () => {
    const form = document.getElementById('consentForm');
    const checkbox = document.getElementById('termsCheckbox');
    const submitBtn = form.querySelector('.submit-btn');
    const messageEl = document.getElementById('formMessage');

    // Update submit button state based on checkbox
    checkbox.addEventListener('change', () => {
        updateSubmitButton();
    });

    // Handle form submission
    form.addEventListener('submit', (e) => {
        e.preventDefault();

        // Validate checkbox
        if (!checkbox.checked) {
            messageEl.textContent = 'Please agree to the terms of use.';
            messageEl.className = 'form-message error';
            checkbox.focus();
            return;
        }

        // Show success message
        messageEl.textContent = 'Thank you! You have agreed to the terms of use.';
        messageEl.className = 'form-message success';

        // Simulate form submission (in a real app, send data to server)
        setTimeout(() => {
            messageEl.textContent = '';
            messageEl.className = 'form-message';
        }, 3000);
    });

    function updateSubmitButton() {
        submitBtn.disabled = !checkbox.checked;
    }

    // Initial state
    updateSubmitButton();
});

